def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != 0]
    if not cells:
        return [row[:] for row in grid]

    # The colored marks lie on diagonals; use the direction with fewer
    # distinct marked diagonals.
    options = []
    for kind in ("diff", "sum"):
        coord = (lambda r, c: c - r) if kind == "diff" else (lambda r, c: r + c)
        groups = {}
        for r, c, color in cells:
            groups.setdefault(coord(r, c), set()).add(color)
        options.append((len(groups), kind, coord, groups))

    options.sort(key=lambda x: x[0])
    for _, kind, coord, groups in options:
        for period in range(1, max(h, w) + 1):
            mapping = {}
            valid = True
            for diagonal, colors in groups.items():
                if len(colors) != 1:
                    valid = False
                    break
                residue = diagonal % period
                color = next(iter(colors))
                if residue in mapping and mapping[residue] != color:
                    valid = False
                    break
                mapping[residue] = color
            if valid and len(mapping) == period:
                return [[mapping[coord(r, c) % period] for c in range(w)]
                        for r in range(h)]

    return [row[:] for row in grid]
